+// ===== LOCALSTORAGE =====
+function loadData() {
+  try {
+    const raw = localStorage.getItem('wb_literacy_data');
+    if (raw) return JSON.parse(raw);
+  } catch(e) {}
+  return null;
+}
+
+function saveData(data) {
+  localStorage.setItem('wb_literacy_data', JSON.stringify(data));
+}
+
+function getData() {
+  let data = loadData();
+  if (!data) {
+    // Initialize with defaults - pre-populate one overdue example
+    const yesterday = new Date();
+    yesterday.setDate(yesterday.getDate() - 1);
+    const yesterdayStr = yesterday.getFullYear() + '-' + String(yesterday.getMonth()+1).padStart(2,'0') + '-' + String(yesterday.getDate()).padStart(2,'0');
+    data = {
+      parentPassword: '1234',
+      dailyChars: [...DEFAULT_DAILY_CHARS],
+      learnedChars: {},
+      dailyCompleted: {},
+      yesterdayIncomplete: ['火'], // Example: "火" wasn't finished yesterday → overdue today
+      points: 15,
+      rewards: JSON.parse(JSON.stringify(DEFAULT_REWARDS)),
+      redeemedRewards: [],
+      lastDate: yesterdayStr,
+    };
+    saveData(data);
+  }
+  // Check if new day - roll over: carry yesterday's incomplete to today
+  const today = getDateStr();
+  if (data.lastDate && data.lastDate !== today) {
+    // Find chars that weren't completed yesterday
+    const prevCompleted = data.dailyCompleted || {};
+    const prevIncomplete = data.dailyChars.filter(c => !prevCompleted[c]);
+    if (prevIncomplete.length > 0) {
+      data.yesterdayIncomplete = prevIncomplete;
+    }
+    data.dailyCompleted = {};
+    data.lastDate = today;
+    saveData(data);
+  }
+  return data;
+}
+
+function getDateStr() {
+  const d = new Date();
+  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
+}
+
+// ===== UI HELPERS =====
+function toast(msg, cls) {
+  const c = document.getElementById('toastContainer');
+  const el = document.createElement('div');
+  el.className = 'toast ' + (cls||'');
+  el.textContent = msg;
+  c.appendChild(el);
+  setTimeout(() => { el.style.opacity = '0'; el.style.transition = 'opacity 0.3s'; }, 1800);
+  setTimeout(() => el.remove(), 2200);
+}
+
+function showConfirm(title, msg, onConfirm) {
+  const modal = document.getElementById('confirmModal');
+  const content = document.getElementById('confirmContent');
+  content.innerHTML = '<h3>' + title + '</h3><p style="margin-bottom:16px;font-size:15px;">' + msg + '</p>' +
+    '<div style="display:flex;gap:10px;justify-content:center;">' +
+    '<button class="btn btn-outline btn-sm" onclick="document.getElementById(\'confirmModal\').classList.add(\'hidden\')">取消</button>' +
+    '<button class="btn btn-primary btn-sm" id="confirmOkBtn">确认</button></div>';
+  modal.classList.remove('hidden');
+  document.getElementById('confirmOkBtn').addEventListener('click', function() {
+    modal.classList.add('hidden');
+    onConfirm();
+  });
+}
+
+function confetti() {
+  const container = document.getElementById('confettiContainer');
+  const colors = ['#FF6B6B','#4ECDC4','#FFE66D','#A78BFA','#51CF66','#FFA94D'];
+  for (let i = 0; i < 40; i++) {
+    const el = document.createElement('div');
+    el.style.cssText = 'position:absolute;width:10px;height:10px;border-radius:3px;background:' +
+      colors[Math.floor(Math.random()*colors.length)] +
+      ';left:' + Math.random()*100 + '%;top:-20px;animation:drop ' + (1+Math.random()*2) +
+      's ease-out forwards;animation-delay:' + (Math.random()*0.5) + 's;';
+    container.appendChild(el);
+    setTimeout(() => el.remove(), 3000);
+  }
+  // Add keyframe if not exist
+  if (!document.getElementById('confettiStyle')) {
+    const style = document.createElement('style');
+    style.id = 'confettiStyle';
+    style.textContent = '@keyframes drop { to { top:110%; opacity:0; transform:rotate(720deg); } }';
+    document.head.appendChild(style);
+  }
+}
