+function renderTodayBar() {
+  const data = getData();
+  const container = document.getElementById('todayChars');
+  const hint = document.getElementById('todayHint');
+  const completed = data.dailyCompleted || {};
+  const yesterdayInc = data.yesterdayIncomplete || [];
+
+  container.innerHTML = '';
+
+  // Show yesterday's incomplete (overdue) first
+  if (yesterdayInc.length > 0) {
+    const overdueLabel = document.createElement('span');
+    overdueLabel.style.cssText = 'font-size:13px;color:#E53E3E;font-weight:700;margin-right:4px;display:flex;align-items:center;';
+    overdueLabel.innerHTML = '⚠️ 昨天没做完：';
+    container.appendChild(overdueLabel);
+
+    yesterdayInc.forEach(char => {
+      const tag = document.createElement('span');
+      tag.className = 'today-char-tag overdue';
+      tag.textContent = char;
+      tag.addEventListener('click', function() {
+        if (currentMode !== 'child') return;
+        const d = getData();
+        if (!d.dailyCompleted) d.dailyCompleted = {};
+        if (d.dailyCompleted[char]) {
+          d.dailyCompleted[char] = false;
+        } else {
+          d.dailyCompleted[char] = true;
+          d.points += 10;
+          // Remove from yesterdayIncomplete
+          d.yesterdayIncomplete = (d.yesterdayIncomplete || []).filter(c => c !== char);
+          saveData(d);
+          toast('⭐ +10分！补上了「' + char + '」', 'success');
+          confetti();
+        }
+        saveData(d);
+        renderTodayBar();
+        renderCards();
+        renderRewards();
+      });
+      container.appendChild(tag);
+    });
+
+    // Separator
+    const sep = document.createElement('span');
+    sep.style.cssText = 'width:100%;height:1px;margin:6px 0;';
+    container.appendChild(sep);
+  }
+
+  let allDone = true;
+  data.dailyChars.forEach(char => {
+    // Skip if already shown as overdue
+    if (yesterdayInc.includes(char) && !completed[char]) {
+      allDone = false;
+      return;
+    }
+    const tag = document.createElement('span');
+    tag.className = 'today-char-tag';
+    tag.textContent = char;
+    if (completed[char]) {
+      tag.classList.add('done');
+    } else {
+      allDone = false;
+    }
+    tag.addEventListener('click', function() {
+      if (currentMode !== 'child') return;
+      const d = getData();
+      if (!d.dailyCompleted) d.dailyCompleted = {};
+      if (d.dailyCompleted[char]) {
+        d.dailyCompleted[char] = false;
+      } else {
+        d.dailyCompleted[char] = true;
+        d.points += 10;
+        saveData(d);
+        toast('⭐ +10分！学会了「' + char + '」', 'success');
+        confetti();
+      }
+      saveData(d);
+      renderTodayBar();
+      renderCards();
+      renderRewards();
+    });
+    container.appendChild(tag);
+  });
+
+  if (allDone && yesterdayInc.length === 0 && data.dailyChars.length > 0) {
+    hint.textContent = '🎉 太棒了！今天 5 个字都学完啦！';
+    hint.style.color = '#51CF66';
+  } else {
+    const left = data.dailyChars.filter(c => !completed[c]).length + yesterdayInc.filter(c => !completed[c]).length;
+    hint.textContent = '点击汉字标记为"已学会"，还差 ' + left + ' 个';
+    hint.style.color = '';
+  }
+}
+
+function renderCards() {
+  const data = getData();
+  const grid = document.getElementById('cardsGrid');
