+}
+
+function saveDailyChars() {
+  const data = getData();
+  saveData(data);
+  toast('✅ 今日任务已保存！', 'success');
+  renderTodayBar();
+  renderCards();
+}
+
+// ===== WORD PRACTICE =====
+let wordAnswered = {};
+
+function renderWordPractice() {
+  const data = getData();
+  currentWordChars = [...data.dailyChars];
+  if (currentWordChars.length === 0) {
+    document.getElementById('wordTargetChar').textContent = '?';
+    document.getElementById('wordOptions').innerHTML = '<div style="color:#999;text-align:center;padding:20px;">请先在家长模式设置今日汉字</div>';
+    return;
+  }
+  currentWordIdx = 0;
+  wordAnswered = {};
+  renderWordQuestion();
+}
+
+function renderWordQuestion() {
+  const char = currentWordChars[currentWordIdx];
+  const info = CHAR_LIBRARY.find(c => c.char === char);
+  if (!info) return;
+
+  document.getElementById('wordTargetChar').textContent = char;
+  document.getElementById('wordFeedback').textContent = '';
+  document.getElementById('wordProgress').textContent = '第 ' + (currentWordIdx+1) + ' / ' + currentWordChars.length + ' 个字';
+
+  // Generate options: correct words + distractors
+  const correctWords = [...info.words];
+  const allWords = [];
+  CHAR_LIBRARY.forEach(c => {
+    if (c.char !== char) {
+      c.words.forEach(w => allWords.push(w));
+    }
+  });
+  // Shuffle and pick 4 distractors
+  const distractors = [];
+  const shuffled = [...allWords].sort(() => Math.random() - 0.5);
+  for (let i = 0; i < shuffled.length && distractors.length < 4; i++) {
+    if (!correctWords.includes(shuffled[i])) {
+      distractors.push(shuffled[i]);
+    }
+  }
+
+  const options = [...correctWords, ...distractors].sort(() => Math.random() - 0.5);
+  const container = document.getElementById('wordOptions');
+  container.innerHTML = '';
+
+  const key = char;
+  wordAnswered[key] = wordAnswered[key] || { correct: 0, total: correctWords.length, done: false };
+
+  options.forEach(word => {
+    const btn = document.createElement('button');
+    btn.className = 'word-opt';
+    btn.textContent = word;
+    btn.addEventListener('click', function() {
+      if (wordAnswered[key].done) return;
+      if (correctWords.includes(word)) {
+        btn.classList.add('correct');
+        wordAnswered[key].correct++;
+        if (wordAnswered[key].correct >= wordAnswered[key].total) {
+          wordAnswered[key].done = true;
+          const data = getData();
+          data.points += 5;
+          saveData(data);
+          document.getElementById('wordFeedback').textContent = '🎉 太厉害了！全部找对啦！+5分';
+          document.getElementById('wordFeedback').style.color = '#51CF66';
+          renderRewards();
+          confetti();
+          updateBackupHint();
+        } else {
+          document.getElementById('wordFeedback').textContent = '✅ 找到「' + word + '」，还有哦~';
+          document.getElementById('wordFeedback').style.color = '#51CF66';
+        }
+      } else {
+        btn.classList.add('wrong');
+        document.getElementById('wordFeedback').textContent = '❌ 「' + word + '」里没有「' + char + '」哦';
+        document.getElementById('wordFeedback').style.color = '#E53E3E';
+      }
+    });
+    container.appendChild(btn);
+  });
+}
+
+function nextWord() {
+  if (currentWordIdx < currentWordChars.length - 1) {
+    currentWordIdx++;
+    renderWordQuestion();
+  }
+}
+function prevWord() {
+  if (currentWordIdx > 0) {
+    currentWordIdx--;
+    renderWordQuestion();
+  }
+}
+
+// ===== GAME =====
+function renderGame() {
+  gameRound = 0;
+  gameScore = 0;
+  gameLocked = false;
+  document.getElementById('gameRoundScore').textContent = '0';
+  nextGameRound();
+}
+
+function nextGameRound() {
+  if (currentMode !== 'child') return;
+  gameLocked = false;
+  gameRound++;
+  document.getElementById('gameRoundScore').textContent = gameScore;
+
+  const data = getData();
+  const pool = data.dailyChars.length > 0 ? data.dailyChars : CHAR_LIBRARY.map(c => c.char).slice(0, 5);
+  const correctChar = pool[Math.floor(Math.random() * pool.length)];
+  const info = CHAR_LIBRARY.find(c => c.char === correctChar);
+
+  // Question
+  const questionTypes = [
+    '点击图片对应的汉字',
+    '找一找：哪一个是"${char}"？',
+    '这个图是哪个字？'
+  ];
+  const qType = questionTypes[Math.floor(Math.random() * 3)];
+  const questionText = qType.replace('${char}', correctChar);
+
+  document.getElementById('gameQuestion').textContent = questionText;
+  document.getElementById('gameImage').innerHTML = info ? info.svg : '';
+
+  // Options: correct + 3 random others
+  const options = [correctChar];
+  const others = CHAR_LIBRARY.filter(c => c.char !== correctChar).map(c => c.char);
+  const shuffledOthers = [...others].sort(() => Math.random() - 0.5);
+  for (let i = 0; i < 3 && i < shuffledOthers.length; i++) {
+    options.push(shuffledOthers[i]);
+  }
+  const shuffledOptions = options.sort(() => Math.random() - 0.5);
+
+  const container = document.getElementById('gameOptions');
+  container.innerHTML = '';
+  shuffledOptions.forEach(char => {
+    const btn = document.createElement('button');
+    btn.className = 'game-opt-btn';
+    btn.textContent = char;
+    btn.addEventListener('click', function() {
+      if (gameLocked) return;
+      gameLocked = true;
+      if (char === correctChar) {
+        btn.classList.add('correct');
+        gameScore += 10;
+        document.getElementById('gameRoundScore').textContent = gameScore;
+        const data = getData();
+        data.points += 10;
+        saveData(data);
+        toast('⭐ +10分！答对啦！', 'success');
+        confetti();
+        renderRewards();
+        updateBackupHint();
+      } else {
+        btn.classList.add('wrong');
+        // Highlight correct answer
+        setTimeout(() => {
+          container.querySelectorAll('.game-opt-btn').forEach(b => {
+            if (b.textContent === correctChar) b.classList.add('correct');
+          });
+        }, 400);
+      }
+    });
+    container.appendChild(btn);
+  });
+
+  // Stars
+  const starsEl = document.getElementById('gameStars');
+  starsEl.innerHTML = '';
+  const stars = Math.min(3, Math.floor(gameScore / 30) + 1);
+  for (let i = 0; i < 3; i++) {
+    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
+    svg.setAttribute('viewBox', '0 0 24 24');
+    svg.setAttribute('class', 'star-icon ' + (i < stars ? 'earned' : 'empty'));
+    svg.innerHTML = '<polygon points="12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26"/>';
+    starsEl.appendChild(svg);
+  }
+}
+
+// ===== REWARDS =====
+function renderRewards() {
+  const data = getData();
+  document.getElementById('pointsDisplay').textContent = data.points;
+
+  const container = document.getElementById('rewardsList');
+  container.innerHTML = '';
+  data.rewards.forEach(reward => {
+    const redeemed = (data.redeemedRewards || []).includes(reward.id);
+    const item = document.createElement('div');
+    item.className = 'reward-item';
+
+    let btnClass = 'reward-btn ';
+    let btnText = '';
+    let disabled = false;
+    if (redeemed) {
+      btnClass += 'redeemed';
+      btnText = '已兑换 ✓';
+      disabled = true;
+    } else if (data.points >= reward.cost) {
+      btnClass += 'available';
+      btnText = '兑换 ' + reward.cost + '分';
+    } else {
+      btnClass += 'locked';
+      btnText = '还差 ' + (reward.cost - data.points) + '分';
+      disabled = true;
+    }
+
+    item.innerHTML = `
+      <div class="reward-info">
+        <div class="reward-name">${getRewardIcon(reward.icon)} ${reward.name}</div>
+        <div class="reward-cost">需要 ${reward.cost} ⭐</div>
+      </div>
+      <button class="${btnClass}" ${disabled ? 'disabled' : ''} onclick="redeemReward('${reward.id}')">${btnText}</button>
+    `;
+    container.appendChild(item);
+  });
+}
+
+function getRewardIcon(icon) {
+  const icons = {
+    tv: '<svg width="20" height="20" viewBox="0 0 24 24" fill="#A78BFA"><rect x="2" y="3" width="20" height="15" rx="2"/><polyline points="7,21 17,21" stroke="#A78BFA" stroke-width="2"/></svg>',
+    candy: '<svg width="20" height="20" viewBox="0 0 24 24" fill="#FF6B6B"><circle cx="12" cy="12" r="10"/><path d="M8 8 L16 16 M16 8 L8 16" stroke="#fff" stroke-width="2"/></svg>',
+    play: '<svg width="20" height="20" viewBox="0 0 24 24" fill="#4ECDC4"><polygon points="6,3 20,12 6,21"/></svg>',
+  };
+  return icons[icon] || '🎁';
+}
+
+function redeemReward(id) {
+  const data = getData();
+  const reward = data.rewards.find(r => r.id === id);
+  if (!reward) return;
+  if ((data.redeemedRewards || []).includes(id)) return;
+  if (data.points < reward.cost) return;
+
+  showConfirm('兑换确认', '确定要用 ' + reward.cost + ' 积分兑换「' + reward.name + '」吗？', function() {
+    const d = getData();
+    if (d.points < reward.cost) { toast('积分不足'); return; }
+    d.points -= reward.cost;
+    if (!d.redeemedRewards) d.redeemedRewards = [];
+    d.redeemedRewards.push(id);
+    saveData(d);
+    renderRewards();
+    toast('🎉 兑换成功！快去享受「' + reward.name + '」吧！', 'success');
+    confetti();
+  });
+}
+
+// ===== PARENT REWARDS MANAGEMENT =====
+function renderParentRewards() {
+  const data = getData();
+  const container = document.getElementById('parentRewards');
+  container.innerHTML = '';
+  data.rewards.forEach((reward, idx) => {
+    const div = document.createElement('div');
+    div.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:8px;';
+    div.innerHTML = `
+      <span style="flex:1;">${reward.name} - ${reward.cost}分</span>
+      <button class="btn btn-outline btn-sm" onclick="editReward(${idx})" style="padding:6px 12px;min-height:36px;">编辑</button>
+      <button class="btn btn-outline btn-sm" onclick="deleteReward(${idx})" style="padding:6px 12px;min-height:36px;color:#E53E3E;border-color:#E53E3E;">删除</button>
+    `;
+    container.appendChild(div);
+  });
+}
+
+function addReward() {
+  const name = prompt('奖励名称（如：看10分钟动画片）：');
+  if (!name) return;
+  const cost = parseInt(prompt('需要多少积分？'));
+  if (!cost || cost <= 0) return;
+  const data = getData();
+  data.rewards.push({ id: 'r' + Date.now(), name, cost, icon: 'play' });
+  saveData(data);
+  renderParentRewards();
+  renderRewards();
+}
+
+function editReward(idx) {
+  const data = getData();
+  const r = data.rewards[idx];
+  const name = prompt('奖励名称：', r.name);
+  if (!name) return;
+  const cost = parseInt(prompt('需要多少积分？', r.cost));
+  if (!cost || cost <= 0) return;
+  r.name = name;
+  r.cost = cost;
+  saveData(data);
+  renderParentRewards();
+  renderRewards();
+}
+
+function deleteReward(idx) {
+  const data = getData();
+  data.rewards.splice(idx, 1);
+  saveData(data);
+  renderParentRewards();
+  renderRewards();
+}
+
+// ===== MODE SWITCH =====
+function switchMode(mode) {
+  currentMode = mode;
+  document.getElementById('childModeBtn').classList.toggle('active', mode === 'child');
+  document.getElementById('parentModeBtn').classList.toggle('active', mode === 'parent');
+
+  // Show/hide panels
+  document.getElementById('panel-cards').style.display = mode === 'child' ? '' : 'none';
+  document.getElementById('panel-words').style.display = mode === 'child' ? '' : 'none';
+  document.getElementById('panel-game').style.display = mode === 'child' ? '' : 'none';
+  document.getElementById('panel-rewards').style.display = mode === 'child' ? '' : 'none';
+  document.getElementById('panel-parent').style.display = mode === 'parent' ? 'block' : 'none';
+
+  // Tabs visible only in child mode
+  document.getElementById('mainTabs').style.display = mode === 'child' ? '' : 'none';
+
+  if (mode === 'child') {
+    document.getElementById('panel-cards').classList.add('active');
