+
+function closePwdModal() {
+  document.getElementById('passwordModal').classList.add('hidden');
+}
+
+function openChangePwd() {
+  document.getElementById('changePwdModal').classList.remove('hidden');
+  document.getElementById('newPwdInput').value = '';
+  document.getElementById('newPwdError').textContent = '';
+  setTimeout(() => document.getElementById('newPwdInput').focus(), 100);
+}
+
+function changePassword() {
+  const input = document.getElementById('newPwdInput').value;
+  if (!/^\d{4}$/.test(input)) {
+    document.getElementById('newPwdError').textContent = '请输入 4 位数字密码';
